function validate([s]) {
  if (s.length < 1) return 's must not be empty.';
  if (/[^0-9+\-() ]/.test(s)) return 's may only contain digits, +, -, parentheses and spaces.';
  const LIMIT = 2 ** 31;
  const stack = [];
  let result = 0, sign = 1, expect = 'start';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === ' ') continue;
    if (ch >= '0' && ch <= '9') {
      if (expect === 'after') return 'Two numbers need an operator between them.';
      let value = 0;
      while (i < s.length && s[i] >= '0' && s[i] <= '9') value = value * 10 + Number(s[i++]);
      i--;
      if (value >= LIMIT) return 'Every number must fit in a 32-bit integer.';
      result += sign * value;
      if (result < -LIMIT || result >= LIMIT) return 'Every intermediate value must fit in a 32-bit integer.';
      expect = 'after';
    } else if (ch === '(') {
      if (expect === 'after') return 'An operator is missing before "(".';
      stack.push(result, sign);
      result = 0; sign = 1; expect = 'start';
    } else if (ch === ')') {
      if (expect !== 'after' || !stack.length) return 'The parentheses are not balanced or a group is empty.';
      const outerSign = stack.pop();
      result = stack.pop() + outerSign * result;
      if (result < -LIMIT || result >= LIMIT) return 'Every intermediate value must fit in a 32-bit integer.';
      expect = 'after';
    } else {
      if (expect === 'operand') return 'Two operators cannot be next to each other.';
      if (expect === 'start' && ch === '+') return '"+" cannot be used as a unary sign.';
      sign = ch === '+' ? 1 : -1;
      expect = 'operand';
    }
  }
  if (expect !== 'after') return 's must end with a number or ")".';
  if (stack.length) return 'The parentheses are not balanced.';
  return null;
}

