function calculate(s) {
  // Recursive descent over the text with spaces removed.
  const text = s.split(' ').join('');
  let pos = 0;
  const isDigit = c => c !== undefined && c >= '0' && c <= '9';
  function operand() {
    if (text[pos] === '-') { pos++; return -operand(); }
    if (text[pos] === '(') { pos++; const inner = expression(); pos++; return inner; }
    let value = 0;
    while (isDigit(text[pos])) value = value * 10 + (text.charCodeAt(pos++) - 48);
    return value;
  }
  function expression() {
    let total = operand();
    while (text[pos] === '+' || text[pos] === '-') {
      const op = text[pos++];
      const next = operand();
      total = op === '+' ? total + next : total - next;
    }
    return total;
  }
  return expression();
}

