function generate(rand, size) {
  const large = size === 'large';
  const operands = large ? 900 + Math.floor(rand() * 200) : 1 + Math.floor(rand() * 6);
  const maxValue = large ? 100000 : 12;
  const maxDepth = large ? 30 : 4;
  const space = () => (rand() < (large ? 0.15 : 0.3) ? ' ' : '');
  let out = space();
  let depth = 0;
  let placed = 0;
  let canNegate = true;
  for (;;) {
    while (placed < operands - 1 && depth < maxDepth && rand() < 0.3) {
      if (canNegate && rand() < 0.3) out += '-' + space();
      out += '(' + space();
      depth++;
      canNegate = true;
    }
    if (canNegate && rand() < 0.3) out += '-' + space();
    out += String(Math.floor(rand() * maxValue)) + space();
    placed++;
    while (depth > 0 && rand() < 0.35) { out += ')' + space(); depth--; }
    if (placed >= operands || out.length > 9600) break;
    out += (rand() < 0.5 ? '+' : '-') + space();
    canNegate = false;
  }
  while (depth > 0) { out += ')'; depth--; }
  return [out];
}
